head.script:
scwin.onpageload = function () {
    //console.log($p.getFrameId());
};

scwin.btn_exam4_1_onclick = function (e) {
    var options = {
        type: "iframePopup",
        id: "popup_exam1",
        width: "300px",
        height: "80px",
        top: 0,
        left: 0,
        popupName: "popup_exam1",
        dataObject: {
            type: "json",
            data: {
                "type": "iframePopup"
            },
            name: "exam_param"
        },
        modal : true,
        frameModal : $p.getFrameId(),
        temp : ""
    };

    $p.openPopup("openPopup_options.frameModal_WESE-480_(WSQ-5533)_wframe_P01.xml", options);
};

