scwin.btn_close_onclick = function (e) {
    var popList = $p.getAllPopupList();
    for (var i = popList.length - 1; i >= 0; i--) {
        $p.closePopup(popList[i].id);  // 열려있는 모든 popup을 닫는다. 닫을 때마다 popList가 제거되므로 array를 역순으로 돌아야 한다.
    }
};
